def experiment(inputs):
    trials = inputs.get('trials', [])
    results = []
    def multi_tier_sort_deep(vals):
        if len(vals) <= 1:
            return vals
        mid = len(vals) // 2
        left = multi_tier_sort_deep(vals[:mid])
        right = multi_tier_sort_deep(vals[mid:])
        return sorted(left + right)
    for trial in trials:
        vals = trial.get('values', [])
        results.append(multi_tier_sort_deep(vals))
    return results

